export type ParsedExecuteInstruction<
  TProgram extends string = typeof BOND_LIFECYCLE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    source: TAccountMetas[0];
    mint: TAccountMetas[1];
    destination: TAccountMetas[2];
    authority: TAccountMetas[3];
    extraAccountMetaList: TAccountMetas[4];
    morRegistry: TAccountMetas[5];
    bond: TAccountMetas[6];
    seal: TAccountMetas[7];
    holderSource: TAccountMetas[8];
    holderDestination: TAccountMetas[9];
  };
  data: ExecuteInstructionData;
};

export function parseExecuteInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedExecuteInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      source: getNextAccount(),
      mint: getNextAccount(),
      destination: getNextAccount(),
      authority: getNextAccount(),
      extraAccountMetaList: getNextAccount(),
      morRegistry: getNextAccount(),
      bond: getNextAccount(),
      seal: getNextAccount(),
      holderSource: getNextAccount(),
      holderDestination: getNextAccount(),
    },
    data: getExecuteInstructionDataDecoder().decode(instruction.data),
  };
}
